147	const COLORS = {
148	  ink: 0x241b14,
149	  panel: 0x2f241a,
150	  cream: 0xfff3d6,
151	  kitchen: 0xc9dbd2,
152	  kitchenDark: 0x4f796f,
153	  dining: 0xecc9a8,
154	  wood: 0xb9814f,
155	  pass: 0xf2cc5c,
156	  door: 0xa8c6da,
157	  empty: 0xc7ab86,
158	  occupied: 0xe8825f,
159	  working: 0x3d9b6d,
