    if (brief.last) {
      const room = chipRight - (zone.x + pad) - 6;
      if (room > 60) {
        this.add.text(zone.x + pad, rowOne + 1, `Last: ${brief.last}`, {
          color: "#7f8f83",
          fontFamily: MONO,
          fontSize: compact ? this.fs(6) : this.fs(7),
          wordWrap: { width: room },
          maxLines: 1,
