      }
    }

    // Row two: the single next move, across the full width, tagged so the
    // kind of problem reads before the sentence does.
    const rowTwo = zone.y + (compact ? 13 : 17);
    const tag = this.add
      .text(zone.x + pad, rowTwo, brief.nowLabel, {
