639	  private drawKitchen(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
640	    const zone = layout.kitchen;
641	    const compact = layout.compact;
642	    this.zonePanel(g, zone, COLORS.kitchen, "KITCHEN", compact);
643	
644	    const pad = compact ? 5 : 8;
645	    const top = zone.y + (compact ? 15 : 20);
646	    const oven = this.state.equipment.find((item) => item.kind === "oven");
647	    const stock = Object.values(this.state.inventory).reduce((sum, count) => sum + count, 0);
648	    const stations: Array<{ label: string; sub: string; color: number; action?: string; tip?: string; dim?: boolean }> = [
649	      { label: "PREP", sub: "", color: 0xf1e6c8 },
650	      { label: "PANTRY", sub: `${stock} left`, color: 0xd4b483 },
651	      {
652	        label: "OVEN",
653	        sub: oven?.status === "failed" ? "DEAD — CLICK" : oven?.status === "degraded" ? "limping" : "ready",
654	        color: oven?.status === "failed" ? COLORS.failed : oven?.status === "degraded" ? 0xd6892f : COLORS.working,
655	        action: oven?.status === "failed" ? "inspect_oven" : undefined,
656	        tip: oven?.status === "failed" ? "Fix the oven" : undefined,
657	      },
658	    ];
659	    // The one in-shift purchase on offer — a permanent second pair of hands
660	    // at the stations, paid for out of tonight's own takings. Affordable
661	    // once cash clears the cost; a one-time click, not a recurring cost.
662	    const upgrade = this.state.upgrade;
663	    if (upgrade) {
664	      const affordable = this.state.outcomes.cash >= upgrade.cost;
665	      stations.push(
666	        upgrade.bought
667	          ? { label: upgrade.label.toUpperCase(), sub: "installed", color: 0x8fbfa0 }
668	          : {
669	              label: `+${upgrade.label.toUpperCase()}`,
670	              sub: `$${upgrade.cost} — click`,
671	              color: affordable ? COLORS.pass : 0x5c4a3a,
672	              action: affordable ? "buy_second_stove" : undefined,
673	              tip: affordable ? "Second pair of hands, all shift" : `Need $${upgrade.cost} to install`,
674	              dim: !affordable,
675	            },
676	      );
677	    }
678	
679	    // On a real desktop window this zone can run far taller than these
680	    // cards need — capped height plus vertical centering keeps them a
681	    // sensible size instead of stretching into empty slabs.
682	    const rawStationHeight = (zone.height - (top - zone.y) - pad * (stations.length + 1)) / stations.length;
683	    const stationHeight = Math.min(compact ? 40 : 76, Math.max(14, rawStationHeight));
684	    const groupHeight = stationHeight * stations.length + pad * (stations.length - 1);
685	    const groupTop = top + Math.max(0, (zone.height - (top - zone.y) - groupHeight) / 2);
686	
687	    stations.forEach((station, index) => {
688	      const y = groupTop + index * (stationHeight + pad);
689	      const rect = { x: zone.x + pad, y, width: zone.width - pad * 2, height: stationHeight };
690	      g.fillStyle(station.color, station.dim ? 0.6 : 1);
691	      g.fillRoundedRect(rect.x, rect.y, rect.width, rect.height, 3);
692	      g.lineStyle(1, COLORS.kitchenDark, 0.8);
693	      g.strokeRoundedRect(rect.x, rect.y, rect.width, rect.height, 3);
694	      const broken = station.label === "OVEN" && oven?.status === "failed";
695	      this.add
696	        .text(zone.x + zone.width / 2, y + stationHeight / 2 - (station.sub ? 4 : 0), station.label, {
697	          color: broken ? "#ffffff" : "#2b2118",
698	          fontFamily: MONO,
699	          fontSize: compact ? this.fs(6) : this.fs(8),
700	          fontStyle: "bold",
701	        })
702	        .setOrigin(0.5);
703	      if (station.sub) {
704	        this.add
705	          .text(zone.x + zone.width / 2, y + stationHeight / 2 + 5, station.sub, {
706	            color: broken ? "#ffe2e2" : "#5c4a3a",
707	            fontFamily: MONO,
708	            fontSize: compact ? this.fs(5) : this.fs(6),
709	            fontStyle: "bold",
710	          })
711	          .setOrigin(0.5);
712	      }
713	      if (station.action) this.hotspot(rect, station.action, station.tip);
714	    });
715	  }
716	
717	  private drawPass(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
718	    const zone = layout.pass;
719	    this.zonePanel(g, zone, COLORS.pass, "PASS", layout.compact, true);
720	    this.hotspot(zone, "verify_substitution", "Verify the ticket");
721	    const y = zone.y + zone.height * 0.6;
722	    g.fillStyle(0x7b4c2e);
723	    g.fillRoundedRect(zone.x + 3, y, zone.width - 6, layout.compact ? 12 : 18, 3);
724	    // Plates waiting on the pass = orders cooked but not yet run to a table.
725	    const ready = this.state.orders.filter((order) => order.status === "ready").length;
726	    for (let i = 0; i < Math.min(3, ready); i++) {
727	      g.fillStyle(0xfff3d6);
728	      g.fillCircle(zone.x + zone.width / 2, y + 4 + i * (layout.compact ? 5 : 7), layout.compact ? 2.5 : 3.5);
729	    }
730	    if (ready > 0) {
731	      this.add
732	        .text(zone.x + zone.width / 2, zone.y + zone.height - 4, `${ready}`, {
733	          color: "#2b2118",
734	          fontFamily: MONO,
735	          fontSize: layout.compact ? this.fs(7) : this.fs(9),
736	          fontStyle: "bold",
737	        })
738	        .setOrigin(0.5, 1);
739	    }
740	  }
741	
742	  private drawDining(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
743	    const zone = layout.dining;
744	    const compact = layout.compact;
745	    this.zonePanel(g, zone, COLORS.dining, "DINING", compact);
746	
747	    const tables = this.state.tables.slice(0, 4);
748	    const top = zone.y + (compact ? 15 : 19);
749	    const available = Math.max(24, zone.height - (top - zone.y) - 4);
750	    const cols = tables.length > 2 ? 2 : tables.length || 1;
751	    const rows = Math.ceil(tables.length / cols) || 1;
752	
753	    tables.forEach((table, index) => {
754	      const col = index % cols;
755	      const row = Math.floor(index / cols);
756	      const cx = zone.x + (zone.width * (col + 0.5)) / cols;
757	      const cy = top + (available * (row + 0.5)) / rows;
758	      // Capped at a fixed 18px, tables read as a sparse handful of dots on a
759	      // real desktop window where this zone is much bigger than a 520px
760	      // canvas — let them grow with the room, not just with the cell they
761	      // have to fit in.
762	      const fitsCell = Math.min(zone.width / cols, available / rows) * 0.3;
763	      const styleCap = compact ? 13 : Math.min(32, 18 + Math.max(0, zone.width - 360) * 0.03);
764	      const radius = Math.max(8, Math.min(styleCap, fitsCell));
765	
766	      // Chairs first so the table top sits over them.
767	      const seats = Math.min(table.seats, 4);
768	      for (let seat = 0; seat < seats; seat++) {
769	        const angle = (Math.PI * 2 * seat) / seats - Math.PI / 2;
770	        g.fillStyle(0x8a5a34);
771	        g.fillCircle(cx + Math.cos(angle) * (radius + 5), cy + Math.sin(angle) * (radius + 5), compact ? 2.5 : 3.5);
772	      }
773	      g.fillStyle(table.status === "occupied" ? COLORS.occupied : COLORS.empty);
774	      g.fillCircle(cx, cy, radius);
775	      g.lineStyle(2, COLORS.cream, 0.85);
776	      g.strokeCircle(cx, cy, radius);
777	
778	      const order = this.state.orders.find((o) => o.tableId === table.id && o.status !== "served" && o.status !== "cancelled");
779	      this.add
780	        .text(cx, cy, table.id.replace("table-", "T"), {
