/**
 * Where every part of the restaurant goes, for a given canvas size.
 *
 * The floor is one room drawn at whatever size the window happens to be, so
 * this is the only place that knows how a 520×740 phone-ish canvas and a
 * 1600×1200 desktop window differ. Two knobs come out of it and are handed to
 * every renderer instead of being re-derived:
 *
 * - `compact` — the floor is small enough that labels have to shrink and
 *   ornament has to go.
 * - `scale` — how much bigger than the baseline window this one is, which the
 *   scene multiplies its type sizes by so a 1600px window reads as a bigger
 *   room rather than the same room with the same 6px labels stranded in it.
 *
 * Everything returned is in CSS pixels inside `0..width` × `0..height`.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The window the floor was designed against: scale 1, nothing cramped. */
export const BASE_WIDTH = 520;
export const BASE_HEIGHT = 740;
/**
