    x: margin,
    y: margin,
    width: w - margin * 2,
    height: px(compact ? 34 : 38),
  };
  const brief: ArenaRect = {
    x: margin,
    y: topBar.y + topBar.height + gap,
    width: w - margin * 2,
    height: px(compact ? 28 : 32),
  };

