  const contentBottom = h - margin;
  const spare = Math.max(1, contentBottom - bodyY);

  // The feed goes beside the floor once there is width to spare, and under it
  // otherwise. Whichever it is, it is carved off first and the floor gets
  // what's left — the room is the thing that has to stay usable.
  let feed: ArenaRect;
  let bodyRight = w - margin;
  let bodyBottom = contentBottom;
