    const feedHeight = Math.round(clamp(spare * 0.22, px(96), spare * 0.36));
    feed = { x: margin, y: contentBottom - feedHeight, width: w - margin * 2, height: feedHeight };
    bodyBottom = feed.y - gap;
  }

