  return Math.max(Math.min(value, high), Math.min(low, high));
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(MIN_WIDTH, Math.round(width));
  const h = Math.max(MIN_HEIGHT, Math.round(height));

  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
