/**
 * Staff moving around the floor.
 *
 * The restaurant is one hallway with four stations on it — kitchen, pass,
 * dining floor, door queue — so a cook sent from the stoves to the door has
 * to pass the window and cross the room to get there. That is the whole point
 * of drawing the room at all: a reassignment costs time you can watch, and
 * where somebody *is* explains why the ticket is late.
 *
 * Two rules keep it reading as a room rather than a graph:
 * - the pass and the floor are through-stations, never shortcuts, so
 *   `bfsPath("kitchen", "queue")` names both of them, and
 * - a walk rides the hallway line (`spineY` from the layout) instead of
 *   cutting a diagonal over the tables.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * The hallway, as adjacency: kitchen — pass — floor — queue. Deliberately a
 * line and not a mesh; there is no back door from the stoves to the street.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
} as const;

/** A hurrying-but-not-running restaurant pace. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Two points are the same spot if they are within this many pixels. */
const SAME_POINT_PX = 0.5;

/**
 * The stations to travel through to get from `from` to `to`, both ends
 * included. `bfsPath(x, x)` is just `[x]`.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];

  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node]) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let step: WalkNode | undefined = to;
        while ((step = previous.get(step!)) !== undefined) path.unshift(step);
        return path;
      }
      queue.push(next);
    }
  }
  return [];
}

function same(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) <= SAME_POINT_PX && Math.abs(a.y - b.y) <= SAME_POINT_PX;
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room: step out to the
 * hallway, walk it, then step in to the station. Consecutive points that land
 * on the same spot are dropped, so a leg that is already a straight line
 * stays one hop.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let cursor = start;

  for (const node of nodes) {
    const destination = waypoints[node];
    if (!destination) continue;
    // Same column: walking out to the hallway and straight back would be a
    // detour, not a route — the door stand sits below the hallway and is
    // reached by stepping down off it.
    const legs =
      Math.abs(destination.x - cursor.x) <= SAME_POINT_PX
        ? [destination]
        : [
            { x: cursor.x, y: spineY },
            { x: destination.x, y: spineY },
            destination,
          ];
    for (const leg of legs) {
      const previous = points[points.length - 1] ?? cursor;
      if (same(previous, leg)) continue;
      points.push({ x: leg.x, y: leg.y });
    }
    cursor = destination;
  }
  return points;
}

/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/** Ease in and out of each hop, so a staff member starts and stops like one. */
function ease(t: number): number {
  return 0.5 - Math.cos(Math.PI * Math.min(1, Math.max(0, t))) / 2;
}

type Leg = { point: Point; node: WalkNode };

/**
 * One staff member's position on the floor, in CSS pixels.
 *
 * Owns the pixel truth: the scene rebuilds its avatars from scratch on every
 * repaint, but the walkers outlive those repaints, which is what keeps a walk
 * (or a drag) from being reset by an unrelated state change.
 */
export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  dragging = false;
  /** The station they are standing in — the last one reached, mid-walk. */
  node: WalkNode;

  private legs: Leg[] = [];
  private legIndex = 0;
  private legFrom: Point;
  private legDuration = 0;
  private legElapsed = 0;
  private destination: WalkNode;

  /** `slot` is the pixel position of `node`; the walker starts parked there. */
  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.destination = node;
    this.x = slot.x;
    this.y = slot.y;
    this.legFrom = { x: slot.x, y: slot.y };
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.destination = node;
    this.legs = [];
    this.legIndex = 0;
    this.legElapsed = 0;
    this.legDuration = 0;
    this.legFrom = { x: slot.x, y: slot.y };
    this.walking = false;
  }

  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    const legs: Leg[] = [];
    let cursor: Point = { x: this.x, y: this.y };
    // Per station rather than in one call, so each hop remembers which room it
    // lands in and `node` can advance as the walk passes through.
    for (const node of bfsPath(this.node, target)) {
      for (const point of corridorPoints(cursor, [node], waypoints, spineY)) {
        legs.push({ point, node });
      }
      cursor = waypoints[node] ?? cursor;
    }

    this.destination = target;
    this.legs = legs;
    this.legIndex = 0;
    if (legs.length === 0) {
      // Already standing where they were sent.
      this.node = target;
      this.walking = false;
      return;
    }
    this.walking = true;
    this.beginLeg();
  }

  /**
   * Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns
   * whether the pixel position changed.
   */
  step(dtMs: number, speed: number): boolean {
    if (!this.walking || this.dragging) return false;
    if (!(dtMs > 0) || !(speed > 0)) return false;

    const wasX = this.x;
    const wasY = this.y;
    let budget = dtMs * speed;

    while (budget > 0 && this.legIndex < this.legs.length) {
      const leg = this.legs[this.legIndex]!;
      this.legElapsed += budget;
      if (this.legElapsed < this.legDuration) {
        const t = ease(this.legElapsed / this.legDuration);
        this.x = this.legFrom.x + (leg.point.x - this.legFrom.x) * t;
        this.y = this.legFrom.y + (leg.point.y - this.legFrom.y) * t;
        break;
      }
      // Hop finished; carry the overshoot into the next one so a slow frame
      // doesn't stall the walk one hop per frame.
      budget = this.legElapsed - this.legDuration;
      this.x = leg.point.x;
      this.y = leg.point.y;
      this.node = leg.node;
      this.legIndex += 1;
      this.beginLeg();
    }

    if (this.legIndex >= this.legs.length) {
      this.legs = [];
      this.legIndex = 0;
      this.walking = false;
      this.node = this.destination;
    }
    return this.x !== wasX || this.y !== wasY;
  }

  private beginLeg(): void {
    const leg = this.legs[this.legIndex];
    this.legFrom = { x: this.x, y: this.y };
    this.legElapsed = 0;
    if (!leg) {
      this.legDuration = 0;
      return;
    }
    this.legDuration = hopDurationMs(this.legFrom, leg.point);
    const dx = leg.point.x - this.legFrom.x;
    if (Math.abs(dx) > SAME_POINT_PX) this.facing = dx < 0 ? -1 : 1;
  }
}

