/**
 * Holds repaints back while the player is dragging.
 *
 * The arena scene has no diffing layer: every state change tears the whole
 * floor down and builds it again. That is fine sixty times a shift — except
 * while a finger is down on a staff token, because the token being dragged is
 * one of the objects that gets destroyed, and the drag dies with it. A tick
 * landing mid-drag would yank the person out from under the cursor.
 *
 * So a drag is a window where paints are owed rather than performed. However
 * many land during it, exactly one is replayed when the drag ends — the state
 * they add up to is the state the next paint would have drawn anyway.
 *
 * A resize is the exception: it repaints from scratch by itself and takes the
 * drag with it, so anything owed is already paid and a late `dragend` from the
 * pointer that started it owes nothing.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
    this.owed = false;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case
   * the paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (!this.dragging) return true;
    this.owed = true;
    return false;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it
   * (and thus needs to be replayed by the caller now).
   */
  endDrag(): boolean {
    this.dragging = false;
    const owed = this.owed;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

