import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints on the spot when nothing is being dragged", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
    // Nothing was held back, so the end of a drag that never happened owes
    // nothing either.
    expect(gate.endDrag()).toBe(false);
  });

  test("holds every paint that lands during a drag and replays exactly one", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    // One repaint, not three: the caller already drew the state they add up to.
    expect(gate.endDrag()).toBe(false);
  });

  test("a drag nothing happened during owes no repaint", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("paints normally again once the drag is over", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.endDrag();
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize drops the drag and clears what it owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    // The resize repainted from scratch, so the pointer's late dragend has
    // nothing left to replay.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a resize with no drag open leaves the gate open", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("a fresh drag starts owing nothing, whatever the last one did", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });
});

