    expect(restaurantArenaLayout(4000, 4000).scale).toBeLessThanOrEqual(1.9);
  });

  test("a small window stays compact and stops growing its text", () => {
    expect(restaurantArenaLayout(440, 900).compact).toBe(true);
    expect(restaurantArenaLayout(1200, 400).compact).toBe(true);
    expect(restaurantArenaLayout(520, 740).compact).toBe(false);
    expect(restaurantArenaLayout(1200, 900).compact).toBe(false);
    // A window compact on one axis and enormous on the other still gets
    // baseline type: there is no room to spend on bigger labels.
    expect(restaurantArenaLayout(1400, 400).scale).toBe(1);
  });

  test("the feed goes beside the floor once there is width for it", () => {
    const stacked = restaurantArenaLayout(520, 740);
    expect(stacked.feedBeside).toBe(false);
    expect(stacked.feed.y).toBeGreaterThan(stacked.tickets.y);
    expect(stacked.feed.x).toBe(stacked.tickets.x);

    const beside = restaurantArenaLayout(1000, 800);
    expect(beside.feedBeside).toBe(true);
    // Beside means a tall rail to the right of the room, not a strip under it.
    expect(beside.feed.x).toBeGreaterThan(beside.dining.x + beside.dining.width);
    expect(beside.feed.y).toBeLessThanOrEqual(beside.kitchen.y);
    expect(beside.feed.height).toBeGreaterThan(beside.dining.height);
    expect(restaurantArenaLayout(599, 800).feedBeside).toBe(false);
    expect(restaurantArenaLayout(600, 800).feedBeside).toBe(true);
  });

  test("the host stand keeps a hittable size at any window size, inside the door", () => {
    for (const [width, height] of SIZES) {
      const { door, doorStand } = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(doorStand.width, where).toBeGreaterThanOrEqual(56);
      expect(doorStand.height, where).toBeGreaterThanOrEqual(22);
      expect(doorStand.x, where).toBeGreaterThanOrEqual(door.x);
      expect(doorStand.x + doorStand.width, where).toBeLessThanOrEqual(door.x + door.width);
      expect(doorStand.y, where).toBeGreaterThanOrEqual(door.y);
      expect(doorStand.y + doorStand.height, where).toBeLessThanOrEqual(door.y + door.height);
    }
  });

  test("the hallway line runs through the pass, and the stations stand on it", () => {
    for (const [width, height] of SIZES) {
      const { pass, dining, kitchen, spineY, waypoints } = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(spineY, where).toBeGreaterThanOrEqual(pass.y);
      expect(spineY, where).toBeLessThanOrEqual(pass.y + pass.height);
      expect(waypoints.kitchen.y, where).toBe(spineY);
      expect(waypoints.pass.y, where).toBe(spineY);
      expect(waypoints.floor.y, where).toBe(spineY);
      // In the rooms they name, left to right in the order staff walk them.
      expect(waypoints.kitchen.x, where).toBeGreaterThan(kitchen.x);
      expect(waypoints.kitchen.x, where).toBeLessThan(kitchen.x + kitchen.width);
      expect(waypoints.pass.x, where).toBeGreaterThan(waypoints.kitchen.x);
      expect(waypoints.floor.x, where).toBeGreaterThan(waypoints.pass.x);
      expect(waypoints.floor.x, where).toBeLessThan(dining.x + dining.width);
    }
  });

  test("the queue waypoint stands the host on the door stand", () => {
    for (const [width, height] of SIZES) {
      const { doorStand, waypoints, spineY } = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(waypoints.queue.x, where).toBeGreaterThanOrEqual(doorStand.x);
      expect(waypoints.queue.x, where).toBeLessThanOrEqual(doorStand.x + doorStand.width);
      expect(waypoints.queue.y, where).toBeGreaterThanOrEqual(doorStand.y);
      expect(waypoints.queue.y, where).toBeLessThanOrEqual(doorStand.y + doorStand.height);
      // The door is off the hallway — that step down is the walk to the door.
      expect(waypoints.queue.y, where).toBeGreaterThan(spineY);
    }
  });

  test("a bigger window spends its room on the floor, not on chrome alone", () => {
    const small = restaurantArenaLayout(BASE_WIDTH, BASE_HEIGHT);
    const big = restaurantArenaLayout(1400, 1100);
    expect(big.dining.width).toBeGreaterThan(small.dining.width);
    expect(big.dining.height).toBeGreaterThan(small.dining.height);
    expect(big.topBar.height).toBeGreaterThan(small.topBar.height);
  });

  test("absurd sizes are clamped rather than producing negative rooms", () => {
    for (const [width, height] of [[0, 0], [-10, 50], [80, 90]] as [number, number][]) {
      const layout = restaurantArenaLayout(width, height);
      for (const [name, rect] of rects(layout)) {
        expect(rect.width, `${name} at ${width}x${height}`).toBeGreaterThan(0);
        expect(rect.height, `${name} at ${width}x${height}`).toBeGreaterThan(0);
      }
    }
  });
});

