import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const layout = restaurantArenaLayout(520, 740);
const waypoints = layout.waypoints;
const spineY = layout.spineY;

/** Walk to completion in small frames, the way the scene's update loop does. */
function runToRest(walker: StaffWalker, speed = 1, frameMs = 16): number {
  let frames = 0;
  while (walker.walking && frames < 100_000) {
    walker.step(frameMs, speed);
    frames += 1;
  }
  return frames;
}

describe("WALK_GRAPH", () => {
  test("is one hallway: kitchen — pass — floor — queue", () => {
    expect(WALK_GRAPH.kitchen).toEqual(["pass"]);
    expect(WALK_GRAPH.pass).toEqual(["kitchen", "floor"]);
    expect(WALK_GRAPH.floor).toEqual(["pass", "queue"]);
    expect(WALK_GRAPH.queue).toEqual(["floor"]);
  });

  test("every link is walkable in both directions", () => {
    for (const [node, neighbours] of Object.entries(WALK_GRAPH) as [WalkNode, readonly WalkNode[]][]) {
      for (const neighbour of neighbours) {
        expect(WALK_GRAPH[neighbour]).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  test("the pass and the floor are through-stations, not shortcuts", () => {
    // There is no back door from the stoves to the street: a cook sent to the
    // door passes the window and crosses the room to get there.
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  test("names both ends of the walk", () => {
    expect(bfsPath("kitchen", "pass")).toEqual(["kitchen", "pass"]);
    expect(bfsPath("pass", "queue")).toEqual(["pass", "floor", "queue"]);
    expect(bfsPath("floor", "kitchen")).toEqual(["floor", "pass", "kitchen"]);
  });

  test("staying put is a path of one", () => {
    for (const node of Object.keys(WALK_GRAPH) as WalkNode[]) {
      expect(bfsPath(node, node)).toEqual([node]);
    }
  });

  test("finds the shortest route between every pair of stations", () => {
    const nodes = Object.keys(WALK_GRAPH) as WalkNode[];
    for (const from of nodes) {
      for (const to of nodes) {
        const path = bfsPath(from, to);
        expect(path[0]).toBe(from);
        expect(path[path.length - 1]).toBe(to);
        // Every consecutive pair is an actual link, so nobody walks through a wall.
        for (let i = 1; i < path.length; i++) {
          expect(WALK_GRAPH[path[i - 1]!]).toContain(path[i]!);
        }
      }
    }
  });
});

describe("corridorPoints", () => {
  test("rides the hallway instead of cutting across the room", () => {
    const points = corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY);
    expect(points.length).toBeGreaterThan(0);
    // Only the last hop leaves the hallway, and it is the step down onto the
    // door stand — nothing in between drifts off the line.
    for (const point of points.slice(0, -1)) expect(point.y).toBe(spineY);
    expect(points[points.length - 1]).toEqual(waypoints.queue);
    expect(points.some((point) => point.x === waypoints.pass.x && point.y === spineY)).toBe(true);
    expect(points.some((point) => point.x === waypoints.floor.x && point.y === spineY)).toBe(true);
  });

  test("a walker already on the hallway takes one hop per room", () => {
    expect(corridorPoints(waypoints.kitchen, ["pass"], waypoints, spineY)).toEqual([waypoints.pass]);
    expect(corridorPoints(waypoints.kitchen, bfsPath("kitchen", "floor"), waypoints, spineY)).toEqual([
      waypoints.pass,
      waypoints.floor,
    ]);
  });

  test("steps out to the hallway first when it starts off it", () => {
    const dropped: Point = { x: waypoints.floor.x + 40, y: spineY + 60 };
    const points = corridorPoints(dropped, bfsPath("queue", "kitchen").slice(1), waypoints, spineY);
    expect(points[0]).toEqual({ x: dropped.x, y: spineY });
    expect(points[points.length - 1]).toEqual(waypoints.kitchen);
    for (const point of points) expect(point.y).toBe(spineY);
  });

  test("a move in the same column goes straight rather than via the hallway", () => {
    const below: Point = { x: waypoints.queue.x, y: spineY + 80 };
    expect(corridorPoints(below, ["queue"], waypoints, spineY)).toEqual([waypoints.queue]);
  });

  test("standing still is no walk at all", () => {
    expect(corridorPoints(waypoints.pass, [], waypoints, spineY)).toEqual([]);
    expect(corridorPoints(waypoints.pass, ["pass"], waypoints, spineY)).toEqual([]);
    expect(corridorPoints(waypoints.pass, bfsPath("pass", "pass"), waypoints, spineY)).toEqual([]);
  });
});

describe("hopDurationMs", () => {
  test("covers 200 pixels a second", () => {
    expect(WALK_SPEED_PX_PER_SEC).toBe(200);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 200, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBe(500);
    expect(hopDurationMs({ x: 10, y: 10 }, { x: 10, y: 10 })).toBe(0);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 30, y: 40 })).toBe(250);
  });
});

describe("StaffWalker", () => {
  test("starts parked on its slot, facing the room", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    expect(walker.node).toBe("kitchen");
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
    expect(walker.walking).toBe(false);
    expect(walker.dragging).toBe(false);
    expect(walker.facing).toBe(1);
    // Nothing to advance, so nothing moves.
    expect(walker.step(16, 1)).toBe(false);
  });

  test("walks the hallway to its target and lands exactly on the slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.walking).toBe(true);

    let leftTheHallway = false;
    let sawPass = false;
    while (walker.walking) {
      walker.step(16, 1);
      if (walker.x >= waypoints.pass.x) sawPass = true;
      if (walker.y !== spineY) leftTheHallway = true;
      // The room is only ever left by the door: while still short of the
      // stand's column, the walk stays on the line.
      if (walker.x < waypoints.queue.x - 1) expect(walker.y).toBe(spineY);
    }
    expect(sawPass).toBe(true);
    expect(leftTheHallway).toBe(true);
    expect(walker.node).toBe("queue");
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
    expect(walker.walking).toBe(false);
  });

  test("takes about as long as the distance says, and faster at 4x", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    const frames = runToRest(walker, 1);

    const straight = new StaffWalker("kitchen", waypoints.kitchen);
    straight.setTarget("queue", waypoints, spineY);
    const rushed = runToRest(straight, 4);
    expect(rushed).toBeLessThan(frames / 3);

    // A walk across the whole floor is seconds, not a teleport and not a crawl.
    const seconds = (frames * 16) / 1000;
    expect(seconds).toBeGreaterThan(1);
    expect(seconds).toBeLessThan(12);
  });

  test("eases each hop instead of moving at a constant rate", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("pass", waypoints, spineY);
    const total = hopDurationMs(waypoints.kitchen, waypoints.pass);
    const step = total / 10;

    walker.step(step, 1);
    const opening = Math.abs(walker.x - waypoints.kitchen.x);
    const before = walker.x;
    // Halfway through the hop the same slice of time covers more ground.
    walker.step(total / 2 - step, 1);
    walker.step(step, 1);
    const middle = Math.abs(walker.x - before) - Math.abs(walker.x - before) + Math.abs(walker.x - before);
    expect(middle).toBeGreaterThan(opening);
    expect(walker.walking).toBe(true);
  });

  test("faces the way it is walking", () => {
    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", waypoints, spineY);
    walker.step(16, 1);
    expect(walker.facing).toBe(-1);
    runToRest(walker);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(16, 1);
    expect(walker.facing).toBe(1);
  });

  test("a paused shift freezes the floor", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("floor", waypoints, spineY);
    expect(walker.step(16, 0)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.walking).toBe(true);
    expect(walker.step(16, 1)).toBe(true);
  });

  test("a walker under the cursor is not also walking itself", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.dragging = true;
    const { x, y } = walker;
    expect(walker.step(200, 1)).toBe(false);
    expect(walker.x).toBe(x);
    expect(walker.y).toBe(y);
    walker.dragging = false;
    expect(walker.step(200, 1)).toBe(true);
  });

  test("snap drops the walk and puts them down where they were dropped", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(100, 1);
    walker.snap(waypoints.floor, "floor");
    expect(walker.node).toBe("floor");
    expect(walker.x).toBe(waypoints.floor.x);
    expect(walker.y).toBe(waypoints.floor.y);
    expect(walker.walking).toBe(false);
    expect(walker.step(16, 1)).toBe(false);
  });

  test("being sent where it already stands is not a walk", () => {
    const walker = new StaffWalker("floor", waypoints.floor);
    walker.setTarget("floor", waypoints, spineY);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("floor");
  });

  test("a shifted slot in the same room is a short walk, not a jump", () => {
    const walker = new StaffWalker("floor", waypoints.floor);
    const stacked = { ...waypoints, floor: { x: waypoints.floor.x + 22, y: waypoints.floor.y } };
    walker.setTarget("floor", stacked, spineY);
    expect(walker.walking).toBe(true);
    runToRest(walker);
    expect(walker.x).toBe(stacked.floor.x);
    expect(walker.node).toBe("floor");
  });

  test("a re-order mid-walk turns around from where they actually are", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    while (walker.walking && walker.node !== "floor") walker.step(16, 1);
    expect(walker.node).toBe("floor");
    walker.setTarget("kitchen", waypoints, spineY);
    runToRest(walker);
    expect(walker.node).toBe("kitchen");
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
  });

  test("one enormous frame still arrives, rather than stalling a hop a frame", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.step(60_000, 1)).toBe(true);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("queue");
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
  });

  test("walks the hallway at every window size", () => {
    for (const [width, height] of [[320, 240], [520, 740], [1400, 1000]] as [number, number][]) {
      const room = restaurantArenaLayout(width, height);
      const walker = new StaffWalker("queue", room.waypoints.queue);
      walker.setTarget("kitchen", room.waypoints, room.spineY);
      runToRest(walker);
      expect(walker.node, `${width}x${height}`).toBe("kitchen");
      expect(walker.x, `${width}x${height}`).toBe(room.waypoints.kitchen.x);
      expect(walker.y, `${width}x${height}`).toBe(room.waypoints.kitchen.y);
    }
  });
});

