    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    const frames = runToRest(walker, 1);

    const straight = new StaffWalker("kitchen", waypoints.kitchen);
    straight.setTarget("queue", waypoints, spineY);
    const rushed = runToRest(straight, 4);
    expect(rushed).toBeLessThan(frames / 3);

    // A walk across the whole floor is seconds, not a teleport and not a crawl.
    const seconds = (frames * 16) / 1000;
    expect(seconds).toBeGreaterThan(1);
    expect(seconds).toBeLessThan(12);
  });

  test("eases each hop instead of moving at a constant rate", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("pass", waypoints, spineY);
    const total = hopDurationMs(waypoints.kitchen, waypoints.pass);
    const step = total / 10;

    walker.step(step, 1);
    const opening = Math.abs(walker.x - waypoints.kitchen.x);
    const before = walker.x;
    // Halfway through the hop the same slice of time covers more ground.
    walker.step(total / 2 - step, 1);
    walker.step(step, 1);
    const middle = Math.abs(walker.x - before) - Math.abs(walker.x - before) + Math.abs(walker.x - before);
    expect(middle).toBeGreaterThan(opening);
    expect(walker.walking).toBe(true);
  });

  test("faces the way it is walking", () => {
    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", waypoints, spineY);
    walker.step(16, 1);
    expect(walker.facing).toBe(-1);
    runToRest(walker);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(16, 1);
    expect(walker.facing).toBe(1);
  });

  test("a paused shift freezes the floor", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("floor", waypoints, spineY);
    expect(walker.step(16, 0)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.walking).toBe(true);
    expect(walker.step(16, 1)).toBe(true);
  });

  test("a walker under the cursor is not also walking itself", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.dragging = true;
    const { x, y } = walker;
    expect(walker.step(200, 1)).toBe(false);
    expect(walker.x).toBe(x);
    expect(walker.y).toBe(y);
    walker.dragging = false;
    expect(walker.step(200, 1)).toBe(true);
  });

  test("snap drops the walk and puts them down where they were dropped", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(100, 1);
    walker.snap(waypoints.floor, "floor");
    expect(walker.node).toBe("floor");
    expect(walker.x).toBe(waypoints.floor.x);
    expect(walker.y).toBe(waypoints.floor.y);
    expect(walker.walking).toBe(false);
    expect(walker.step(16, 1)).toBe(false);
  });

  test("being sent where it already stands is not a walk", () => {
    const walker = new StaffWalker("floor", waypoints.floor);
    walker.setTarget("floor", waypoints, spineY);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("floor");
  });

  test("a shifted slot in the same room is a short walk, not a jump", () => {
    const walker = new StaffWalker("floor", waypoints.floor);
    const stacked = { ...waypoints, floor: { x: waypoints.floor.x + 22, y: waypoints.floor.y } };
    walker.setTarget("floor", stacked, spineY);
    expect(walker.walking).toBe(true);
    runToRest(walker);
    expect(walker.x).toBe(stacked.floor.x);
    expect(walker.node).toBe("floor");
  });

  test("a re-order mid-walk turns around from where they actually are", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    while (walker.walking && walker.node !== "floor") walker.step(16, 1);
    expect(walker.node).toBe("floor");
    walker.setTarget("kitchen", waypoints, spineY);
    runToRest(walker);
    expect(walker.node).toBe("kitchen");
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
  });

  test("one enormous frame still arrives, rather than stalling a hop a frame", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.step(60_000, 1)).toBe(true);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("queue");
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
  });

  test("walks the hallway at every window size", () => {
    for (const [width, height] of [[320, 240], [520, 740], [1400, 1000]] as [number, number][]) {
      const room = restaurantArenaLayout(width, height);
      const walker = new StaffWalker("queue", room.waypoints.queue);
      walker.setTarget("kitchen", room.waypoints, room.spineY);
      runToRest(walker);
      expect(walker.node, `${width}x${height}`).toBe("kitchen");
      expect(walker.x, `${width}x${height}`).toBe(room.waypoints.kitchen.x);
      expect(walker.y, `${width}x${height}`).toBe(room.waypoints.kitchen.y);
    }
  });
});

