/**
 * Two people in the same room stand next to each other rather than on top
 * of each other, centred on the room's waypoint so a crowded kitchen spills
 * evenly to both sides instead of walking out the right-hand wall.
 */
private stackedSlot(location: Location, index: number, crowd: number, layout: RestaurantArenaLayout): { x: number; y: number } {
  const slot = layout.waypoints[location];
  const step = layout.compact ? 17 : this.sp(22);
  return { x: Math.round(slot.x + (index - (crowd - 1) / 2) * step), y: slot.y };
}

/**
 * Every worker's slot for this paint, keyed by role: the same map the
 * walkers are steered by and the drop handler reassigns into.
 */
private staffSlots(layout: RestaurantArenaLayout): Map<Role, { location: Location; slot: { x: number; y: number } }> {
  const crowds = new Map<Location, number>();
  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    crowds.set(location, (crowds.get(location) ?? 0) + 1);
  }
  const placed = new Map<Location, number>();
  const slots = new Map<Role, { location: Location; slot: { x: number; y: number } }>();
  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const index = placed.get(location) ?? 0;
    placed.set(location, index + 1);
    slots.set(worker.role, { location, slot: this.stackedSlot(location, index, crowds.get(location) ?? 1, layout) });
  }
  return slots;
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const slots = this.staffSlots(layout);
  this.staffTokens.clear();

  for (const worker of this.state.workers) {
    const placement = slots.get(worker.role);
    if (!placement) continue;
    const { location, slot } = placement;
    const walker = this.walker(worker.role, location, slot);
