1125	  private drawWorkers(layout: RestaurantArenaLayout): void {
1126	    const compact = layout.compact;
1127	    const slots = this.staffSlots(layout);
1128	    this.staffTokens.clear();
1129	
1130	    for (const worker of this.state.workers) {
1131	      const placement = slots.get(worker.role);
1132	      if (!placement) continue;
1133	      const { location, slot } = placement;
1134	      const walker = this.walker(worker.role, location, slot);
1135	      // The room they were sent to is where they walk to — the hallway, not a
1136	      // diagonal over the tables — with their own stacked slot as the last
1137	      // step so a reshuffle in one room is a sidestep rather than a jump.
1138	      if (!walker.dragging && (walker.node !== location || (!walker.walking && (walker.x !== slot.x || walker.y !== slot.y)))) {
1139	        walker.setTarget(location, { ...layout.waypoints, [location]: slot }, layout.spineY);
1140	      }
1141	
1142	      const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
1143	      token.setData("role", worker.role);
1144	      this.staffTokens.set(worker.role, token);
1145	      const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
1146	      const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
1147	      this.drawWorkerBadge(token, status, compact, heldHost);
1148	      this.drawSpeechBubble(token, worker.role, compact);
1149	      this.makeDraggable(token, compact);
1150	    }
1151	  }
1152	
1153	  /** The walker for a role, parked on `slot` the first time we see them. */
1154	  private walker(role: Role, location: Location, slot: { x: number; y: number }): StaffWalker {
1155	    const existing = this.walkers.get(role);
1156	    if (existing) return existing;
1157	    const fresh = new StaffWalker(location, slot);
1158	    this.walkers.set(role, fresh);
1159	    return fresh;
1160	  }
1161	
1162	  // ── Walking and dragging ─────────────────────────────────────────────
1163	
1164	  /**
1165	   * Staff walk in real time, at the shift's own speed: paused is frozen,
1166	   * ×4 is a hustle. Only the token's position is touched here — everything
1167	   * else about an avatar is settled at paint time.
1168	   */
1169	  update(_time: number, delta: number): void {
1170	    if (this.walkers.size === 0) return;
1171	    const speed = this.running ? (this.state.sim?.speed ?? 1) : 0;
1172	    for (const [role, walker] of this.walkers) {
1173	      if (!walker.step(delta, speed)) continue;
1174	      const token = this.staffTokens.get(role);
1175	      if (!token) continue;
1176	      token.setPosition(walker.x, walker.y);
1177	      const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
1178	      figure?.setScale(walker.facing, 1);
1179	    }
1180	  }
1181	
1182	  /**
1183	   * Pick a staff member up and put them in another room. The drop is a real
1184	   * game action (`assign_<role>_<location>`) so it replays like every other
1185	   * one — and because the reassignment comes straight back as a state change,
1186	   * the repaint it triggers is held until the pointer is up (see
1187	   * `RepaintGate`), or the token would be destroyed mid-gesture.
1188	   */
1189	  private bindStaffDragging(): void {
1190	    this.input.on("dragstart", (_pointer: Phaser.Input.Pointer, token: Phaser.GameObjects.Container) => {
1191	      const role = token.getData?.("role") as Role | undefined;
1192	      if (!role) return;
1193	      this.dragRole = role;
1194	      this.repaints.beginDrag();
1195	      const walker = this.walkers.get(role);
1196	      if (walker) walker.dragging = true;
1197	      this.tweens.killTweensOf(token);
1198	      token.setDepth(40);
1199	      token.setAlpha(0.92);
1200	      this.showDropZones();
1201	    });
1202	
1203	    this.input.on("drag", (_pointer: Phaser.Input.Pointer, token: Phaser.GameObjects.Container, x: number, y: number) => {
1204	      const role = this.dragRole;
1205	      if (!role) return;
1206	      token.setPosition(x, y);
1207	      // The walker owns the pixel truth even while the cursor is doing the
1208	      // moving, so a drop that goes nowhere walks home from the drop point
1209	      // instead of snapping back to where the gesture started.
1210	      const walker = this.walkers.get(role);
1211	      if (walker) {
1212	        walker.x = x;
1213	        walker.y = y;
1214	      }
1215	      this.highlightDropZone(this.locationAt(x, y));
1216	    });
1217	
1218	    this.input.on("dragend", (_pointer: Phaser.Input.Pointer, token: Phaser.GameObjects.Container) => {
1219	      const role = this.dragRole;
1220	      this.dragRole = undefined;
1221	      this.clearDropZones();
1222	      token.setAlpha(1);
1223	      token.setDepth(20);
1224	      const walker = role ? this.walkers.get(role) : undefined;
1225	      if (walker) walker.dragging = false;
1226	
1227	      const layout = this.layout;
1228	      const worker = role ? this.state.workers.find((candidate) => candidate.role === role) : undefined;
1229	      const dropped = this.locationAt(token.x, token.y);
1230	
1231	      if (role && walker && layout && worker && dropped && dropped !== worker.location) {
1232	        // They are already standing where the player put them, so they stay
1233	        // there rather than walking back to be walked out again — this is the
1234	        // drag drop `StaffWalker.snap` exists for.
1235	        const crowd = this.state.workers.filter(
1236	          (candidate) => candidate.role !== role && this.visualLocation(candidate) === dropped,
1237	        ).length;
1238	        walker.snap(this.stackedSlot(dropped, crowd, crowd + 1, layout), dropped);
1239	        this.onAction(`assign_${role}_${dropped}`);
1240	      } else if (role && walker && layout) {
1241	        // Dropped on nothing, or back where they came from: walk home.
1242	        const placement = this.staffSlots(layout).get(role);
1243	        if (placement) {
1244	          walker.setTarget(
1245	            placement.location,
1246	            { ...layout.waypoints, [placement.location]: placement.slot },
1247	            layout.spineY,
1248	          );
1249	        }
1250	      }
1251	
1252	      // Whatever the drop changed, one repaint settles it — and after the
1253	      // pointer has been let go of, never during.
1254	      if (this.repaints.endDrag()) this.time.delayedCall(0, () => this.paint());
1255	    });
1256	  }
