1258	  /** Which room a point is in, for a drop. */
1259	  private locationAt(x: number, y: number): Location | undefined {
1260	    const layout = this.layout;
1261	    if (!layout) return undefined;
1262	    const zones: [Location, ArenaRect][] = [
1263	      ["kitchen", layout.kitchen],
1264	      ["pass", layout.pass],
1265	      ["floor", layout.dining],
1266	      ["queue", layout.door],
1267	    ];
1268	    for (const [location, rect] of zones) {
1269	      if (x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height) return location;
1270	    }
1271	    return undefined;
1272	  }
