1274	  /** Outline every room the moment a token is lifted, so the drop is obvious. */
1275	  private showDropZones(): void {
1276	    const layout = this.layout;
1277	    if (!layout) return;
1278	    for (const rect of [layout.kitchen, layout.pass, layout.dining, layout.door]) {
