private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const slots = this.staffSlots(layout);
  this.staffTokens.clear();

  for (const worker of this.state.workers) {
    const placement = slots.get(worker.role);
    if (!placement) continue;
    const { location, slot } = placement;
    const walker = this.walker(worker.role, location, slot);
    // The room they were sent to is where they walk to — the hallway, not a
    // diagonal over the tables — with their own stacked slot as the last
    // step so a reshuffle in one room is a sidestep rather than a jump.
    if (!walker.dragging && (walker.node !== location || (!walker.walking && (walker.x !== slot.x || walker.y !== slot.y)))) {
      walker.setTarget(location, { ...layout.waypoints, [location]: slot }, layout.spineY);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    token.setData("role", worker.role);
    this.staffTokens.set(worker.role, token);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeDraggable(token, compact);
  }
}

/** The walker for a role, parked on `slot` the first time we see them. */
private walker(role: Role, location: Location, slot: { x: number; y: number }): StaffWalker {
  const existing = this.walkers.get(role);
  if (existing) return existing;
  const fresh = new StaffWalker(location, slot);
  this.walkers.set(role, fresh);
  return fresh;
}

// ── Walking and dragging ─────────────────────────────────────────────

/**
 * Staff walk in real time, at the shift's own speed: paused is frozen,
 * ×4 is a hustle. Only the token's position is touched here — everything
 * else about an avatar is settled at paint time.
 */
update(_time: number, delta: number): void {
  if (this.walkers.size === 0) return;
  const speed = this.running ? (this.state.sim?.speed ?? 1) : 0;
  for (const [role, walker] of this.walkers) {
    if (!walker.step(delta, speed)) continue;
    const token = this.staffTokens.get(role);
    if (!token) continue;
    token.setPosition(walker.x, walker.y);
    const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
    figure?.setScale(walker.facing, 1);
  }
}

/**
 * Pick a staff member up and put them in another room. The drop is a real
 * game action (`assign_<role>_<location>`) so it replays like every other
 * one — and because the reassignment comes straight back as a state change,
 * the repaint it triggers is held until the pointer is up (see
 * `RepaintGate`), or the token would be destroyed mid-gesture.
 */
private bindStaffDragging(): void {
  this.input.on("dragstart", (_pointer: Phaser.Input.Pointer, token: Phaser.GameObjects.Container) => {
    const role = token.getData?.("role") as Role | undefined;
    if (!role) return;
    this.dragRole = role;
    this.repaints.beginDrag();
    const walker = this.walkers.get(role);
    if (walker) walker.dragging = true;
    this.tweens.killTweensOf(token);
    token.setDepth(40);
    token.setAlpha(0.92);
    this.showDropZones();
  });

  this.input.on("drag", (_pointer: Phaser.Input.Pointer, token: Phaser.GameObjects.Container, x: number, y: number) => {
    const role = this.dragRole;
    if (!role) return;
    token.setPosition(x, y);
    // The walker owns the pixel truth even while the cursor is doing the
    // moving, so a drop that goes nowhere walks home from the drop point
    // instead of snapping back to where the gesture started.
    const walker = this.walkers.get(role);
    if (walker) {
      walker.x = x;
      walker.y = y;
    }
    this.highlightDropZone(this.locationAt(x, y));
  });

  this.input.on("dragend", (_pointer: Phaser.Input.Pointer, token: Phaser.GameObjects.Container) => {
    const role = this.dragRole;
    this.dragRole = undefined;
    this.clearDropZones();
    token.setAlpha(1);
    token.setDepth(20);
    const walker = role ? this.walkers.get(role) : undefined;
    if (walker) walker.dragging = false;

    const layout = this.layout;
    const worker = role ? this.state.workers.find((candidate) => candidate.role === role) : undefined;
    const dropped = this.locationAt(token.x, token.y);

    if (role && walker && layout && worker && dropped && dropped !== worker.location) {
      // They are already standing where the player put them, so they stay
      // there rather than walking back to be walked out again — this is the
      // drag drop `StaffWalker.snap` exists for.
      const crowd = this.state.workers.filter(
        (candidate) => candidate.role !== role && this.visualLocation(candidate) === dropped,
      ).length;
      walker.snap(this.stackedSlot(dropped, crowd, crowd + 1, layout), dropped);
      this.onAction(`assign_${role}_${dropped}`);
    } else if (role && walker && layout) {
      // Dropped on nothing, or back where they came from: walk home.
      const placement = this.staffSlots(layout).get(role);
      if (placement) {
        walker.setTarget(
          placement.location,
          { ...layout.waypoints, [placement.location]: placement.slot },
          layout.spineY,
        );
      }
    }

    // Whatever the drop changed, one repaint settles it — and after the
    // pointer has been let go of, never during.
    if (this.repaints.endDrag()) this.time.delayedCall(0, () => this.paint());
  });
}

/** Which room a point is in, for a drop. */
private locationAt(x: number, y: number): Location | undefined {
  const layout = this.layout;
  if (!layout) return undefined;
  const zones: [Location, ArenaRect][] = [
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["floor", layout.dining],
    ["queue", layout.door],
  ];
  for (const [location, rect] of zones) {
    if (x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height) return location;
  }
  return undefined;
}

/** Outline every room the moment a token is lifted, so the drop is obvious. */
private showDropZones(): void {
  const layout = this.layout;
  if (!layout) return;
  for (const rect of [layout.kitchen, layout.pass, layout.dining, layout.door]) {
    const outline = this.add.rectangle(rect.x, rect.y, rect.width, rect.height).setOrigin(0, 0);
    outline.setStrokeStyle(2, COLORS.cream, 0.5);
    outline.setDepth(38);
    this.dragZones.push(outline);
  }
}

private highlightDropZone(location: Location | undefined): void {
  const layout = this.layout;
  if (!layout) return;
  const order: Location[] = ["kitchen", "pass", "floor", "queue"];
  this.dragZones.forEach((outline, index) => {
    const hot = order[index] === location;
    outline.setStrokeStyle(hot ? 3 : 2, hot ? COLORS.pass : COLORS.cream, hot ? 0.95 : 0.5);
  });
}

private clearDropZones(): void {
  for (const outline of this.dragZones) outline.destroy();
  this.dragZones = [];
}

private makeDraggable(token: Phaser.GameObjects.Container, compact: boolean): void {
  // Before the doors open the crew is a roster on a card, not people on a
  // floor — there is nowhere to send them yet.
  if (!this.state.sim?.started) return;
  const unit = (compact ? 2 : 2.6) * this.textScale;
  const width = unit * 11;
  const height = unit * 15;
  token.setInteractive(
    new Phaser.Geom.Rectangle(-width / 2, -height / 2, width, height),
    Phaser.Geom.Rectangle.Contains,
  );
  this.input.setDraggable(token);
}

/**
 * The service log tells the same story in a rail nobody has to be
 * looking at — a bubble over the actual person doing the thinking is
 * what makes the floor read as staffed by someone, not just occupied.
 */
private latestLineFor(role: Role): string | undefined {
  const feed = this.state.feed;
  if (!feed || feed.length === 0) return undefined;
  for (let i = feed.length - 1; i >= Math.max(0, feed.length - 6); i--) {
    const entry = feed[i]!;
    if (entry.voice === role && (entry.kind === "thought" || entry.kind === "action")) return entry.text;
  }
  return undefined;
}

